+package transport
+
+import (
+	cryptotls "crypto/tls"
+	"fmt"
+	"net"
+	"strconv"
+	"time"
+)
+
+const (
+	defaultPort = 8080
+	dialTimeout = 3 * time.Second
+)
+
+// endpoint is a network address for a sibling service: a host, a port
+// (always in range 1-65535, falling back to defaultPort otherwise), and
+// whether it speaks TLS.
+type endpoint struct {
+	host string
+	port int
+	tls  bool
+}
+
+// newEndpoint builds an endpoint, normalizing an out-of-range or zero port
+// to defaultPort so every other method can trust port is always valid.
+func newEndpoint(host string, port int, tls bool) endpoint {
+	if port <= 0 || port > 65535 {
+		port = defaultPort
+	}
+	return endpoint{host: host, port: port, tls: tls}
+}
