@@ -0,0 +1,55 @@
+package transport
+
+import (
+	cryptotls "crypto/tls"
+	"fmt"
+	"net"
+	"strconv"
+	"time"
+)
+
+const (
+	defaultPort = 8080
+	dialTimeout = 3 * time.Second
+)
+
+type endpoint struct {
+	host string
+	port int
+	tls  bool
+}
+
+// newEndpoint normalizes an invalid port to defaultPort so every other method can trust port is always valid.
+func newEndpoint(host string, port int, tls bool) endpoint {
+	if port <= 0 || port > 65535 {
+		port = defaultPort
+	}
+	return endpoint{host: host, port: port, tls: tls}
+}
+
+func (e endpoint) scheme() string {
+	if e.tls {
+		return "https"
+	}
+	return "http"
+}
+
+func (e endpoint) address() string {
+	return net.JoinHostPort(e.host, strconv.Itoa(e.port))
+}
+
+func (e endpoint) url(path string) string {
+	return fmt.Sprintf("%s://%s%s", e.scheme(), e.address(), path)
+}
+
+func (e endpoint) dial() (net.Conn, error) {
+	addr := e.address()
+	conn, err := net.DialTimeout("tcp", addr, dialTimeout)
+	if err != nil {
+		return nil, fmt.Errorf("transport: dial %s: %w", addr, err)
+	}
+	if e.tls {
+		return cryptotls.Client(conn, &cryptotls.Config{ServerName: e.host, MinVersion: cryptotls.VersionTLS12}), nil
+	}
+	return conn, nil
+}

